import unittest

class TestMean(unittest.TestCase):
    def test_empty(self):
        with self.assertRaises(ValueError):
            mean([])
    def test_two(self):
        self.assertEqual(mean([2, 4]), 3)

def memoize(fn):
    cache = {}
    def wrapped(*args):
        if args not in cache:
            cache[args] = fn(*args)
        return cache[args]
    return wrapped
